use vstd::prelude::*;

verus! {

fn less_equal(a: Vec<i8>, b: Vec<i8>) -> (res: Vec<bool>)
    requires
        a.len() == b.len(),
    ensures
        res.len() == a.len(),
    ensures
        forall |i: usize| i < a.len() ==> res[i] == (a[i] <= b[i]),
{
    let n = a.len();
    let mut res: Vec<bool> = Vec::with_capacity(n);
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            res.len() == i,
            forall |j: usize| j < i ==> res[j] == (a[j] <= b[j]),
    {
        // compute the i-th boolean and append it
        res.push(a[i] <= b[i]);
        i += 1;
    }
    res
}

} // end verus!

fn main() {
    // example usage
    let a = vec![1i8, -5, 10, 42];
    let b = vec![2i8, -5, 5, 42];
    let r = less_equal(a.clone(), b.clone());
    assert_eq!(r, vec![true, true, false, true]);
}